CREATE DATABASE IF NOT EXISTS psu_cms CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE psu_cms;
CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content (id INT AUTO_INCREMENT PRIMARY KEY, type VARCHAR(40) NOT NULL, title VARCHAR(220) NOT NULL, slug VARCHAR(240) NOT NULL, body MEDIUMTEXT, summary TEXT, image_path VARCHAR(500), file_path VARCHAR(500), file_name VARCHAR(255), event_date DATETIME NULL, email VARCHAR(190), phone VARCHAR(80), address VARCHAR(255), status ENUM('draft','published') NOT NULL DEFAULT 'draft', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY type_slug (type,slug), KEY type_status (type,status), KEY event_date (event_date));
CREATE TABLE IF NOT EXISTS feedback (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL, subject VARCHAR(220) NOT NULL, message TEXT NOT NULL, status ENUM('new','read') DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_attempts (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL, ip VARCHAR(45) NOT NULL, attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY email_time (email, attempted_at), KEY ip_time (ip, attempted_at));
CREATE TABLE IF NOT EXISTS feedback_attempts (id INT AUTO_INCREMENT PRIMARY KEY, ip VARCHAR(45) NOT NULL, attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY ip_time (ip, attempted_at));
